// Publishes the canonical root-level llms artifacts to the site so the
// deployed domain serves them at /llms.txt, /llms-full.txt and /llms-<area>.txt
// (GEO: AI engines fetch these for structured context). Run as a `prebuild`
// step so the published copies always come from the single source of truth
// (generated by scripts/generate_llms.py, `make llms`) — never committed into
// public/, never drifting.
//
// The per-area shards exist because llms-full.txt is far too large for one
// fetch: a client that truncates reads the first few guides and concludes the
// library is only about those. llms.txt links every shard by name, so all of
// them have to be published or those links 404.
import { copyFileSync, existsSync, mkdirSync, readdirSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");
const publicDir = join(here, "..", "public");

mkdirSync(publicDir, { recursive: true });

const isLlmsArtifact = (name) => /^llms(-[a-z0-9-]+)?\.txt$/.test(name);
const published = readdirSync(repoRoot).filter(isLlmsArtifact).sort();

if (published.length === 0) {
  console.warn("[copy-llms] no llms*.txt found at repo root — run `make llms`");
}

// Drop shards a previous build published that the generator no longer emits:
// regrouping a section renames its shard, and a leftover file would keep
// serving text that llms.txt no longer indexes.
for (const name of readdirSync(publicDir)) {
  if (isLlmsArtifact(name) && !published.includes(name)) {
    rmSync(join(publicDir, name));
    console.log(`[copy-llms] removed stale ${name}`);
  }
}

for (const name of published) {
  const src = join(repoRoot, name);
  if (!existsSync(src)) continue;
  copyFileSync(src, join(publicDir, name));
}
console.log(
  `[copy-llms] published ${published.length} llms artifacts -> site/public/`,
);
